# Cuyahoga County Board of Elections issues list, Nov 3 2026 (English ballot wording).
# (issue no, kind, jurisdiction, SoS place or "county", area, title, ballot text)
CA = "Proposed charter amendment"
LQ = "liquor"
QN = "question"
QUESTIONS = [
 (12, QN, "County of Cuyahoga", "county", "Countywide", CA + ": Article II, Section 2.03 and Article VI, Section 6.04", "Shall Article II, Section 2.03 and Article VI, Section 6.04 of the Charter of the County of Cuyahoga be amended to require that County Council confirm the County Executive’s removal of members of boards, agencies, commissions and authorities as are or may hereafter be created by or pursuant to the Charter, as are provided by general law to be appointed by boards of county commissioners, and on special boards and commissions created by any agreement with another public agency or court order?"),
 (13, QN, "County of Cuyahoga", "county", "Countywide", CA + ": Article V, Section 5.06 (Director of Law)", "Shall Article V, Section 5.06 of the Charter of the County of Cuyahoga be amended to provide that the Director of Law shall provide primary legal representation on labor negotiations, grievances and arbitrations, non-litigation related employment matters, public records matters, risk management functions and activities, and non-litigation related contracts, agreements, debt issuance documents, memoranda of understanding, purchase orders, and other legal instruments entered into by the County Executive on behalf of Cuyahoga County; that the powers and duties of the Director of Law shall include giving written opinions and other legal advice to the Executive, County Council, officers, departments, directors, boards, agencies, commissions, and authorities appointed or established under the various Articles of the Charter, and other County entities whose chief executive officers serve at the pleasure of the County Executive or County Council; that nothing prohibits the County Executive, County Council or other entities established by Charter, Council, or general law, from seeking or obtaining advice from the Prosecuting Attorney; that this Section 5.06 shall not in any way limit the powers and duties of the Prosecuting Attorney as set forth in Section 4.01 and general law; and that in no event shall the Director of Law prosecute, defend, appear in court, or otherwise handle any action in any litigation or litigation-related proceedings on behalf of the County or any of its entities, unless referred to the Law Director by the Prosecuting Attorney?"),
 (14, QN, "County of Cuyahoga", "county", "Countywide", CA + ": Article XII, Section 12.09 (Charter Review Commission)", "Shall Article XII, Section 12.09 of the Charter of the County of Cuyahoga be amended to provide that four (4) members of the Charter Review Commission shall be appointed by the County Executive, and such appointments shall not be subject to Council confirmation; four (4) members shall be appointed by the Council, and such appointments shall not be presented to the County Executive for approval or disapproval; and that one (1) member shall be appointed by the County Executive, subject to confirmation by Council?"),
 (15, LQ, "Bay Village", "BAY VILLAGE", "Bay Village precinct 03-A", "Local liquor option: BAYarts & Entire Campus (Sunday)", "Shall the sale of beer, wine and mixed beverages be permitted for sale on Sunday by BAYarts & Entire Campus an applicant for a D-6 liquor permit who is engaged in the business of a non-profit arts organization at 28601 & 28795 Lake Road, Bay Village, OH 44140 in this precinct?"),
 (16, QN, "City of Bedford Heights", "BEDFORD HEIGHTS", "Bedford Heights", CA + ": Section 8.02 (Director of Law)", "Shall Section 8.02 of the Charter of the City of Bedford Heights be amended to provide that the Director of Law shall be appointed by the Mayor rather than the Council, and shall serve at the pleasure of the Mayor?"),
 (17, QN, "City of Bedford Heights", "BEDFORD HEIGHTS", "Bedford Heights", CA + ": Section 13.05 (Director of Finance bond)", "Shall Section 13.05 of the Charter of the City of Bedford Heights be amended to permit the Director of Finance's bond requirement to be satisfied by one or more insurance or risk-management policies or programs designed to protect the City against loss caused by dishonest acts, theft, or failure to faithfully perform official duties, including, without limitation, a Government Entity Crime Policy with a Faithful Performance of Duty endorsement, or any successor or substantially equivalent form of coverage maintained by the City, in an amount not less than that otherwise required for the bond, so long as such policy is maintained, in lieu of a separate surety bond?"),
 (19, QN, "City of Berea", "BEREA", "Berea", CA + ": Article IV, Item 1 (Council terms)", "Shall Article IV, Item 1 of the Charter of the City of Berea be amended by expanding the terms for all members of Council and the President of Council from two (2) to four (4) year terms, starting for the regular municipal election to take place in 2027?"),
 (20, QN, "City of Berea", "BEREA", "Berea", CA + ": Article XIII, Item 2 (petition deadline)", "Shall Article XIII, Item 2 of the Charter of the City of Berea be amended to change the deadline for candidates submitting nominating petitions for municipal elective office of the City of Berea from not less than sixty (60) days to not less than ninety (90) days prior to the date of the primary election for such offices?"),
 (22, QN, "City of Broadview Heights", "BROADVIEW HEIGHTS", "Broadview Heights", CA + ": Article III, Section 1(b) (council term limits)", "Shall Article III, Section 1(b), of the Charter of the City of Broadview Heights be amended to provide that no person shall hold the office of councilperson for more than three (3) consecutive four (4) year terms or twelve (12) consecutive years; and that terms served prior to the effective date of this amendment shall not be counted?"),
 (23, QN, "City of Broadview Heights", "BROADVIEW HEIGHTS", "Broadview Heights", CA + ": Article IV, Section 1 (mayor term limits)", "Shall Article IV, Section 1 of the Charter of the City of Broadview Heights be amended to provide that no person shall hold office of Mayor for more than three (3) consecutive 4 year terms or twelve (12) consecutive years unless one (1) full term or more had elapsed since that person last held the office of Mayor; and that terms served prior to the effective date of this amendment shall not be counted?"),
 (24, QN, "City of Broadview Heights", "BROADVIEW HEIGHTS", "Broadview Heights", CA + ": Article IV, Section 4(d) (mayor's contracts)", "Shall Article IV, of the Charter of the City of Broadview Heights be amended to add Section 4(d) to provide that the Mayor shall have the authority to enter into contracts on behalf of the City without prior Council approval as required pursuant to Article III, Section 7 of the Charter when the value of the contract is $25,000 or less, provided sufficient funds have otherwise been appropriated by council; and that the $25,000 threshold shall increase annually at a rate of 3% beginning January 1, 2028?"),
 (25, QN, "City of Broadview Heights", "BROADVIEW HEIGHTS", "Broadview Heights", CA + ": Article IV, Section 4(e) (mayor's purchases)", "Shall Article IV, of the Charter of the City of Broadview Heights be amended to add Section 4(e) to provide that the Mayor shall have the authority to make purchases on behalf of the City without prior Council approval when the value of purchase is $25,000 or less, provided sufficient funds have otherwise been appropriated by council; and that the $25,000 threshold shall increase annually at a rate of 3% beginning January 1, 2028?"),
 (26, QN, "City of Broadview Heights", "BROADVIEW HEIGHTS", "Broadview Heights", CA + ": Article V, Section 5(c) (fire stations)", "Shall Article V, Section 5 of the Charter of the City of Broadview Heights be amended to add Section 5(c) to provide that the City of Broadview Heights shall maintain two fire stations within the City, with each fire station having at least one fire truck and one EMS vehicle?"),
 (27, QN, "City of Broadview Heights", "BROADVIEW HEIGHTS", "Broadview Heights", CA + ": Article XI, Section 4 (timing of tax levies)", "Shall Article XI, of the Charter of the City of Broadview Heights be amended to add Section 4 to provide that municipal tax levies can only be placed on the ballot for municipal elections held in November of any calendar year?"),
 (28, QN, "City of Broadview Heights", "BROADVIEW HEIGHTS", "Broadview Heights", CA + ": Article XIV, Section 8(d) (gender-neutral terms)", "Shall Article XIV, Section 8 of the Charter of the City of Broadview Heights be amended to add Section 8(d) to provide that under reprinting(s) of the Charter, any gender-specific terms shall be changed to gender neutral terms?"),
 (29, QN, "City of Brook Park", "BROOK PARK", "Brook Park", CA + ": Article IV, Section 4.04 (officials' compensation)", "Shall Article IV, Section 4.04 of the Charter of the City of Brook Park be amended to remove the requirement that any increase of over three percent (3%) in compensation for any elected City officials be approved by the electorate?"),
 (30, QN, "City of Brook Park", "BROOK PARK", "Brook Park", CA + ": Article XV, Section 15.01(c) (New Community Authority trustees)", "Shall Article XV, Section 15.01(c) of the Charter of the City of Brook Park be amended to provide that elected or appointed officials may serve as trustees for the Brook Park New Community Authority?"),
 (31, QN, "Village of Brooklyn Heights", "BROOKLYN HEIGHTS", "Brooklyn Heights", CA + ": Article II (Council terms)", "Shall Article II of the Charter of the Village of Brooklyn Heights be amended to provide that staggered terms for Council be eliminated; that three (3) Council positions shall be elected at the November 2027 election for a term of two (2) years; and that beginning with the November 2029 regular Village election, all five (5) Council positions shall be elected to four (4) year terms?"),
 (32, QN, "Village of Brooklyn Heights", "BROOKLYN HEIGHTS", "Brooklyn Heights", CA + ": Article IV (Clerk/Treasurer)", "Shall Article IV of the Charter of the Village of Brooklyn Heights be amended to provide that effective April 1, 2030, the Office of the Clerk/Treasurer shall change from an elected position to one appointed by the Mayor, subject to confirmation from the Council; and to remove the qualification that the Clerk/Treasurer shall be a resident and qualified elector of the Village; and to remove the duty that the Clerk/Treasurer shall work in the office within the Village Hall for at least thirty (30) hours a week?"),
 (33, LQ, "City of Cleveland", "CLEVELAND", "Cleveland precinct 03-Q", "Local liquor option: Chillie’s Beverage & Deli (Sunday)", "Shall the sale of wine and mixed beverages be permitted for sale on Sunday by 2976, Inc. (dba Chillie’s Beverage & Deli) an applicant for a D-6 liquor permit who is engaged in the business of operating a carryout/grocery store at 2976 East 116th Street, Cleveland, OH 44120 in this precinct?"),
 (34, LQ, "City of Cleveland", "CLEVELAND", "Cleveland precinct 04-P", "Local liquor option: Old Brooklyn Food Mart (Sunday)", "Shall the sale of wine and mixed beverages be permitted for sale on Sunday by Aarjun Krupa, L.L.C., dba Old Brooklyn Food Mart an applicant for a D-6 liquor permit who is engaged in the business of operating a carryout/grocery store at 4785 Pearl Road, Cleveland, OH 44109 in this precinct?"),
 (35, LQ, "City of Cleveland", "CLEVELAND", "Cleveland precinct 07-C", "Local liquor option: Sunoco One Stop (Sunday)", "Shall the sale of beer be permitted for sale on Sunday by Haba Inc dba Sunoco One Stop an applicant for a D-6 liquor permit, holder of a C-1 liquor permit who is engaged in the business of a convenience store and gas station at 4402 Lorain Avenue, Cleveland, OH 44113 in this precinct?"),
 (36, LQ, "City of Cleveland", "CLEVELAND", "Cleveland precinct 11-L", "Local liquor option: Memphis Mart (Sunday)", "Shall the sale of wine and mixed beverages be permitted for sale on Sunday by Sadguru 1 Krupa, L.L.C., dba Memphis Mart an applicant for a D-6 liquor permit who is engaged in the business of operating a carryout/grocery store at 6226 Memphis Avenue, Cleveland, OH 44144 in this precinct?"),
 (37, LQ, "City of Cleveland", "CLEVELAND", "Cleveland precinct 13-C", "Local liquor option: Convenient Food Mart, Lorain Ave. (Sunday)", "Shall the sale of wine and mixed beverages be permitted for sale on Sunday by Jaspreet, Inc., dba Convenient Food Mart an applicant for a D-6 liquor permit who is engaged in the business of operating a carryout/grocery store at 12520 Lorain Avenue, Cleveland, OH 44111 in this precinct?"),
 (38, LQ, "City of Cleveland", "CLEVELAND", "Cleveland precinct 14-N", "Local liquor option: Convenient Food Mart, Pearl Rd. (Sunday)", "Shall the sale of wine and mixed beverages be permitted for sale on Sunday by Shivay CFM, L.L.C., dba Convenient Food Mart an applicant for a D-6 liquor permit who is engaged in the business of operating a carryout/grocery store at 3753 Pearl Road, Cleveland, OH 44109 in this precinct?"),
 (39, QN, "City of East Cleveland", "EAST CLEVELAND", "East Cleveland", "Proposed municipal income tax (increase to 2.5%)", "Shall the Ordinance providing for a 0.5% levy increase on income, to a rate of a 2.5% levy on income, for the purposes of general municipal operations, maintenance, new equipment, extension and enlargement of municipal services and facilities and capital improvements, commencing January 1, 2027, be passed?"),
 (40, QN, "City of Garfield Heights", "GARFIELD HEIGHTS", "Garfield Heights", CA + ": Sections 7 and 12 (Council terms)", "Shall Sections 7 and 12 of the Charter of the City of Garfield Heights be amended to change the terms of all seven (7) members of Council from two (2) to four (4) years, beginning at the General Election held in November 2029; and to provide that Council shall elect one of its members President of Council at the first meeting in December following the General Election?"),
 (41, QN, "Village of Gates Mills", "GATES MILLS", "Gates Mills", CA + ": Article VIII, Section 5 (land conservation levy renewal)", "Shall Article VIII, Section 5 of the Charter of the Village of Gates Mills be amended to renew an existing tax levy for the public purpose of conserving, retaining, protecting and preserving land, water, forest, open, natural or wetland areas in this Municipality predominantly in their natural, scenic, open or wooded condition or as suitable habitat for fish, plants or wildlife, including the acquisition of such real property or interests therein as may be necessary to carry out that purpose, at a rate not exceeding 1 mill for each one dollar of valuation, which amounts to 10 cents for each one hundred dollars of valuation, for five years, commencing in 2026, first due in calendar year 2027?"),
 (42, QN, "City of Independence", "INDEPENDENCE", "Independence", CA + ": Article III, Section 3 (Mayor at Council meetings)", "Shall Article III, Section 3 of the Charter of the City of Independence be amended to provide that the Mayor shall attend all meetings of the Council, and remove the requirement that the Mayor preside over all meetings of the Council?"),
 (43, QN, "City of Independence", "INDEPENDENCE", "Independence", CA + ": Article IV, Sections 2(a) and 2(b) (Finance Director)", "Shall Article IV, Sections 2(a) and 2(b) of the Charter of the City of Independence be amended to provide that the position of the Finance Director transition from an elected office to a position appointed by the Mayor, effective January 1, 2028, subject to confirmation by at least five (5) members of Council and serving until he or she resigns, dies, or is removed by at least five (5) members of Council; and provide that a Bachelor’s Degree from an accredited college or university and have at least five years of experience in government accounting or public finance be required?"),
 (44, QN, "City of Independence", "INDEPENDENCE", "Independence", CA + ": Article IV, Section 5(a) (Planning Commission appointments)", "Shall Article IV, Section 5(a) of the Charter of the City of Independence be amended to provide that, commencing January 1, 2027, the appointment of three (3) citizen members of the Planning Commission be changed from the Mayor to a majority of the members elected to Council?"),
 (45, QN, "City of Independence", "INDEPENDENCE", "Independence", CA + ": Article IV, Section 5(c) (zoning ordinances)", "Shall Article IV, Section 5(c) of the Charter of the City of Independence be amended to provide that any zoning ordinances, regulations, or amendments passed by Council under this Article IV, Section 5(c) shall not be passed on or as an emergency?"),
 (46, QN, "City of Lakewood", "LAKEWOOD", "Lakewood", CA + ": Section 2.2 (Council vacancies)", "Shall Section 2.2 of the Third Amended Charter of the City of Lakewood be amended to require that prior to making an appointment to a vacancy in Council, remaining members of Council shall first issue an open call for all interested candidates to submit applications and, upon Council's review of the applications, shall hold candidate interviews in public session?"),
 (47, QN, "City of Lakewood", "LAKEWOOD", "Lakewood", CA + ": Section 2.8 (amending ordinances)", "Shall Section 2.8 of the Third Amended Charter of the City of Lakewood be amended to allow the revision, repeal, or amendment of an ordinance or resolution by underlining inserted language and striking through language that is being removed?"),
 (48, QN, "City of Lakewood", "LAKEWOOD", "Lakewood", CA + ": Section 6.7 (officials' compensation)", "Shall Section 6.7 of the Third Amended Charter of the City of Lakewood be amended to provide that on or before March 1 of each odd numbered year, the Civil Service Commission shall set forth the commission's recommendations for the salary and other compensation for the offices of mayor and members of council?"),
 (49, QN, "City of Lakewood", "LAKEWOOD", "Lakewood", CA + ": new Section 7.2 (i) (ward redivision)", "Shall the Third Amended Charter of the City of Lakewood be amended by adding new Section 7.2 (i) to require that, commencing with the Federal decennial census of 2030, the Planning Commission shall review and make, if necessary, appropriate redivisions of the City into four wards, which shall be as nearly equal in population as possible, and composed of contiguous and compact territory, bounded by natural boundaries or street lines; and that any changes made in ward boundaries shall become effective for the next regular municipal election?"),
 (50, QN, "City of Lakewood", "LAKEWOOD", "Lakewood", CA + ": Section 7.5 (charter amendments)", "Shall Section 7.5 of the Third Amended Charter of the City of Lakewood be amended to clarify that amendments to the Charter may be submitted to the registered voters of the city in three manners: upon the recommendation of a two-thirds majority vote of the members of the Charter Review Commission and submission by Council to a vote of the people; by an affirmative vote of Council of at least two-thirds of councilmembers; or upon receipt of a petition signed by not less than ten percent (10%) of the registered voters of the city?"),
 (51, QN, "City of Maple Heights", "MAPLE HEIGHTS", "Maple Heights", CA + ": Article III, Section 1 (Council residency)", "Shall Article III, Section 1 of the Charter of the City of Maple Heights be amended to provide that each member of Council shall have resided continuously in the City for a period of at least two (2) years preceding their election; and that they shall have resided continually in the district from which the Councilperson seeks election, for a period of at least two (2) years preceding their election?"),
 (52, QN, "City of Maple Heights", "MAPLE HEIGHTS", "Maple Heights", CA + ": Article III, Section 3 (absent officers)", "Shall Article III, Section 3 of the Charter of the City of Maple Heights be amended to delete the provision that an elective officer who is absent from the duties of office for three months, or disqualified from office, may continue in office until a successor is qualified?"),
 (53, QN, "City of Maple Heights", "MAPLE HEIGHTS", "Maple Heights", CA + ": Article VII, Section 12 (posting ordinances)", "Shall Article VII, Section 12 of the Charter of the City of Maple Heights be amended to permit ordinances or resolutions embracing the subjects of salaries, the necessity for and intention to install public improvements which contain provisions for assessments against abutting properties, or grants of public utility franchises, be posted on the City’s website and social media accounts and in four (4) public places in the City, said places determined by Council?"),
 (54, QN, "City of Maple Heights", "MAPLE HEIGHTS", "Maple Heights", CA + ": Article XIII, Section 7 (wording correction)", "Shall Article XIII, Section 7 of the Charter of the City of Maple Heights be amended to correct a grammatical error by revising the phrase “committee of the petitions” to “committee of the petitioners?”"),
 (55, QN, "City of Maple Heights", "MAPLE HEIGHTS", "Maple Heights", CA + ": Article XX, Section 2 (Charter Review Commission)", "Shall Article XX, Section 2 of the Charter of the City of Maple Heights be amended to provide that, beginning in January 2031 and each five (5) years thereafter, the Mayor, the Council President, and each member of Council, from within their District, shall appoint one qualified elector of the City and respective District, holding no other office or appointment with the City of Maple Heights, as members of a nine (9) person Charter Review Commission; that the Mayor and President of Council shall appoint one (1) alternate member each, to serve if a Commission member(s) is absent for a meeting; and if a Commission member(s) is absent for a meeting, then one, or both of the alternates, as necessary, may be appointed by a majority of the members present for the meeting to replace the absent member for that meeting only, with all the same rights and duties as the absent member; and to provide for the election of a Chairperson pro tem from among the Commission members?"),
 (56, LQ, "City of Maple Heights", "MAPLE HEIGHTS", "Maple Heights precinct 01-B", "Local liquor option: Dunham Inn (Sunday)", "Shall the sale of wine and mixed beverages and spirituous liquor be permitted for sale on Sunday by Dunham Inn, L.L.C. an applicant for a D-6 liquor permit who is engaged in the business of operating a bar at 6140 Dunham Road, Maple Heights, OH 44137 in this precinct?"),
 (58, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": Section 6.06 (Council-at-large elections)", "Shall Section 6.06 of the Charter of the Village of Oakwood be amended to eliminate the primary and run-off elections for Council-at-large?"),
 (59, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": Section 6.07", "Shall Section 6.07 of the Charter of the Village of Oakwood be amended to eliminate gender-specific language and references to at-large Councilpersons; and to provide that elected officials of the municipality may hold such offices as may be held in an ex-officio capacity?"),
 (60, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": Section 7.01 (size of Council)", "Shall Section 7.01 of the Charter of the Village of Oakwood be amended to reduce the number of members of Council from seven (7) to five (5) members by eliminating the two (2) members elected to Council at large?"),
 (61, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": Section 7.03 (ward boundaries)", "Shall Section 7.03 of the Charter of the Village of Oakwood be amended by repealing outdated ward boundary lines?"),
 (62, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": Section 7.04 (redividing wards)", "Shall Section 7.04 of the Charter of the Village of Oakwood be amended to provide that Council may direct such officials, departments, or employees of the municipality, or may appropriate such funds and contract with a third party, as Council may determine is necessary to redivide the municipality into five wards which shall be as nearly equal in number of persons after each Federal census; and that the Village Engineer shall keep, maintain, and make available for public inspection a map of the Municipality delineating its ward boundaries?"),
 (63, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": Section 7.07 (Council vacancies)", "Shall Section 7.07 of the Charter of the Village of Oakwood be amended to provide that a successor member of Council shall be elected to serve the remainder of the unexpired term of the member in whose office the vacancy occurs at the next regular or primary municipal election if (a) such election shall occur more than one year prior to the expiration of the unexpired term, and (b) the vacancy shall have occurred not less than 120 days prior to such election; that there shall be no primary contest for the election under this Section; that a candidate for office under this Section shall file with the Board of Elections, not less than 60 days before the election; and that a candidate for office under this Section is ineligible if he or she holds a different elective office of the Village at the time of filing his or her nominating petition?"),
 (64, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": Section 7.08 (Council officers)", "Shall Section 7.08 of the Charter of the Village of Oakwood be amended to provide that at Council’s organization meeting in January, or as soon thereafter as is practicably possible, a majority of the members of Council shall elect one of its members as the President of the Council and another of its members President Pro Tempore of Council?"),
 (65, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": Section 7.14 (posting ordinances)", "Shall Section 7.14 of the Charter of the Village of Oakwood be amended to remove the requirement to post ordinances and resolutions at an additional public location within the Village, and eliminate the Clerk’s duty to certify the location of the postings, while retaining postings at Village Hall and on the official Village website?"),
 (66, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": Section 10.11 (zoning notices)", "Shall Section 10.11 of the Charter of the Village of Oakwood be amended to provide the Clerk of Council shall advertise any proposed zoning changes on the official website of the Municipality, in addition to in a newspaper of general circulation?"),
 (67, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": new Section 13.07 (corrections to the Charter)", "Shall the Charter of the Village of Oakwood be amended by adopting new Section 13.07 to provide Council shall be authorized to make typographical corrections to or changes or deletions in, as well as changes in the form of, the Charter; however, the changes shall relate to matters of form; or, to make the Charter consistent with Ohio law, upon advice of the Director of Law; that any such modification, change, or correction shall, in all cases, be approved by resolution of Council, prior to going into effect; that no modification, change or correction shall affect the construction, meaning, substance, or intent of the Charter as adopted and amended by the people, except where the change corrects the Charter to comply with Ohio law?"),
 (68, QN, "Village of Oakwood", "OAKWOOD", "Oakwood", CA + ": new Section 13.08 (ethics standards)", "Shall the Charter of the Village of Oakwood be amended by adopting new Section 13.08 to provide that the standards of ethical conduct and avoidance of conflicts of interest for all elected and appointed officers, officials, and employees of the Municipality shall be those established by the general laws of the State of Ohio, including civil and criminal penalties imposable for violations of such standards?"),
 (69, LQ, "Village of Oakwood", "OAKWOOD", "Oakwood precinct 04-A", "Local liquor option: Roseland Lanes (Sunday)", "Shall the sale of beer, wine and mixed beverages and spirituous liquor be permitted for sale on Sunday by Roseland Lanes Inc an applicant for a D-6 liquor permit who is engaged in the business of bowling lanes, bar and banquet party center at 26383 Broadway Avenue, Oakwood Village, OH 44146 in this precinct?"),
 (71, QN, "City of Olmsted Falls", "OLMSTED FALLS", "Olmsted Falls", "Proposed municipal income tax (increase to 2%)", "Shall the Ordinance providing for a 0.5% levy increase on income, to a rate of a 2% levy on income, for the purposes of general municipal operations, maintenance, new equipment, extension and enlargement of municipal services and facilities and capital improvements; and eliminating the tax credit for income taxes paid to other municipalities by residents of the city, effective January 1, 2027, be passed?"),
 (72, QN, "City of Olmsted Falls", "OLMSTED FALLS", "Olmsted Falls", CA + ": Article III, Section 3.01 (home rule powers)", "Shall Article III, Section 3.01 of the Charter of the City of Olmsted Falls be amended to provide that the Municipality shall have all powers, without limitation, of local self-government and municipal home rule; that no law of the State of Ohio or of the United States shall be imposed upon the city except where mandated by law, unless the city adopts or approves such state or federal law by this Charter or legislative act; that this Charter and city ordinances, rules and regulations shall be construed broadly in favor of the home rule power of the city where possible; and that none of the powers herein shall be withdrawn from the exclusive control of the city, nor shall the corporate existence of the city terminate or merge, nor shall any territory be detached from or annexed to the city without approval of the council and as specified in this Charter?"),
 (73, QN, "City of Olmsted Falls", "OLMSTED FALLS", "Olmsted Falls", CA + ": Article V, Section 5.03(c) (contracts)", "Shall Article V, Section 5.03(c) of the Charter of the City of Olmsted Falls be amended to provide that monetary contracts involving amounts less than the dollar limit set for department heads in the purchasing approval section of the city’s codified ordinances must be reviewed and approved by the law department prior to their execution and shall be entered into and enforced by the Mayor; and that all other contracts require the authority of council for their execution and shall be entered into and enforced by the Mayor?"),
 (74, QN, "City of Olmsted Falls", "OLMSTED FALLS", "Olmsted Falls", CA + ": Article V, Section 5.08 (emergency legislation)", "Shall Article V, Section 5.08 of the Charter of the City of Olmsted Falls be amended to provide that Council may adopt an emergency ordinance or resolution for the efficient operation of the municipality?"),
 (75, QN, "City of Olmsted Falls", "OLMSTED FALLS", "Olmsted Falls", CA + ": Article VII, Section 7.08 (recall elections)", "Shall Article VII, Section 7.08 of the Charter of the City of Olmsted Falls be amended by extending the timeframe for holding a recall election from not fewer than forty (40) days and no more than fifty-five (55) days from the date of the certification of sufficiency of a petition demanding the recall and removal of an elected officer, to not fewer than sixty (60) days and no more than ninety (90) days from the date of the certification of sufficiency of said petition?"),
 (76, QN, "City of Olmsted Falls", "OLMSTED FALLS", "Olmsted Falls", CA + ": Article VIII, Section 8.02 (Director of Finance)", "Shall Article VIII, Section 8.02 of the Charter of the City of Olmsted Falls be amended to provide that the Director of Finance shall have no less than six (6) years of accounting experience, preferably with at least three (3) such years working in municipal government accounting; and remove the requirement that the Director of Finance shall have at least three (3) years’ experience in municipal government accounting?"),
 (77, QN, "Village of Orange", "ORANGE", "Orange", CA + ": Article III, Section 2 (Council qualifications)", "Shall Article III, Section 2 of the Charter of the Village of Orange be amended to revise the qualifications for members of Council to clarify that members of Council may also be members of the Ohio National Guard?"),
 (78, QN, "Village of Orange", "ORANGE", "Orange", CA + ": Article III, Section 4 (Council absences)", "Shall Article III, Section 4 of the Charter of the Village of Orange be amended to provide that grounds for removal for members of Council shall be three unexcused absences from regular meetings in any consecutive twelve (12) month period, rather than three unexcused absences from regular meetings in one calendar year?"),
 (79, QN, "Village of Orange", "ORANGE", "Orange", CA + ": Article IV, Section 2 (Mayor's other offices)", "Shall Article IV, Section 2 of the Charter of the Village of Orange be amended to provide that the Mayor shall not hold any other elected public office, but may hold other public employment; and to provide that if the Mayor ceases to possess any of the qualifications for said office, the Mayor may be removed from office pursuant to the procedure stated in Article IV, Section 8 of the Charter?"),
 (80, QN, "Village of Orange", "ORANGE", "Orange", CA + ": Article IV, Section 5 (executing contracts)", "Shall Article IV, Section 5 of the Charter of the Village of Orange be amended to provide that the Mayor shall execute all contracts, conveyances, evidences of indebtedness and all other instruments to which the Municipality is a party, provided that such execution may be performed by the Mayor's designee at the Mayor's direction, and or via mechanical device operated at the Mayor's direction?"),
 (81, QN, "Village of Orange", "ORANGE", "Orange", CA + ": Article V, Section 2 (Treasurer)", "Shall Article V, Section 2 of the Charter of the Village of Orange be amended to provide that the Treasurer shall be appointed by the Mayor, subject to confirmation by a vote of four (4) members of Council; and that the Treasurer shall be head of the Finance Department?"),
 (82, QN, "Village of Orange", "ORANGE", "Orange", CA + ": Article V, Section 3 (Law Director)", "Shall Article V, Section 3 of the Charter of the Village of Orange be amended to require the Law Director be licensed to practice in the State of Ohio; and to provide Council the authority to appoint special counsel upon the recommendation of Law Director, at the request of the Mayor, or its own initiative?"),
 (83, QN, "Village of Orange", "ORANGE", "Orange", CA + ": Article V, Section 9 (Architectural Board of Review)", "Shall Article V, Section 9 of the Charter of the Village of Orange be amended to provide that a quorum of the Architectural Board of Review shall be four (4) members, at least one (1) of whom shall be an Architect Member; and that Architect Members may also serve as paid consultants to the Village, at the Mayor's direction?"),
 (84, QN, "Village of Orange", "ORANGE", "Orange", CA + ": Article VIII, Sections 3, 4 and 5 (expired levies)", "Shall Article VIII, Sections 3, 4, and 5 of the Charter of the Village of Orange be amended to delete language regarding expired temporary tax levies no longer in collection?"),
 (85, QN, "Village of Orange", "ORANGE", "Orange", CA + ": Article XI (Charter Review Commission)", "Shall Article XI of the Charter of the Village of Orange be amended by reducing the interval for appointing the Charter Review Commission members from eight (8) to six (6) years; to provide that at its first meeting the Commission shall organize and appoint a chair, vice chair, and secretary; that the Commission shall make its recommendations to Council on revisions to the Charter by the first of June next following the appointment of the Commission; and to authorize the engagement of special counsel or other professional assistance for the Commission as Council determines to be appropriate?"),
 (87, LQ, "City of Parma Heights", "PARMA HEIGHTS", "Parma Heights precinct 04-A", "Local liquor option: Santo Matador Street Tacos (Sunday)", "Shall the sale of wine and mixed beverages and spirituous liquor be permitted for sale on Sunday by Matador Parma LLC dba Santo Matador Street Tacos an applicant for a D-6 liquor permit who is engaged in the business of operating a family oriented, full-service Mexican restaurant at 6699 West 130th Street, Parma Heights, OH 44130 in this precinct?"),
 (88, LQ, "City of Parma Heights", "PARMA HEIGHTS", "Parma Heights precinct 04-B", "Local liquor option: Heights Bar and Grill (Sunday)", "Shall the sale of wine and mixed beverages be permitted for sale on Sunday by 12215 Gas LLC dba Heights Bar and Grill an applicant for a D-6 liquor permit, and holder of C-1 and C-2 liquor permits who is engaged in the business of a convenience store and gas station at 12215 Huffman Rd., Parma Heights, Ohio 44130 in this precinct?"),
 (89, QN, "City of Rocky River", "ROCKY RIVER", "Rocky River", CA + ": Article II, Section 1 (Mayor's term)", "Shall Article II, Section 1 of the Charter of the City of Rocky River be amended to provide for a change in the term for Mayor from two (2) to four (4) years; and that beginning with the 2027 municipal election, the Mayor shall be elected every fourth year thereafter for a term of four (4) years?"),
 (90, QN, "City of Rocky River", "ROCKY RIVER", "Rocky River", CA + ": Article II, Section 3 (removal of the Mayor)", "Shall Article II, Section 3 of the Charter of the City of Rocky River be amended to provide that Council may, by a two-thirds (2/3) vote of the members of Council after public hearing, expel or remove the Mayor from office for gross misconduct, malfeasance, nonfeasance, misfeasance in or disqualification for office; for violation of the Mayor’s oath of office; for conviction while in office of a crime involving moral turpitude; for absence without justifiable excuse from three consecutive regular Council meetings; or for mental or physical disability rendering it impossible for the Mayor to perform the duties of Mayor?"),
 (91, QN, "City of Rocky River", "ROCKY RIVER", "Rocky River", CA + ": Article III, Section 2 (Council terms)", "Shall Article III, Section 2 of the Charter of the City of Rocky River be amended to provide for a change in terms of all Members of Council from two (2) to four (4) year terms; that beginning with the 2027 municipal election, Ward council members shall be elected every fourth year for a four (4) year term; and beginning with the 2029 municipal election, At-Large council members shall be elected every fourth year for a four (4) year term?"),
 (92, QN, "City of Rocky River", "ROCKY RIVER", "Rocky River", CA + ": Article IV, Section 2 (A) (Director of Law's term)", "Shall Article IV, Section 2 (A) of the Charter of the City of Rocky River be amended to change the term of the Director of Law from two (2) to four (4) years by providing that beginning with the 2027 municipal election, the Director of Law shall be elected every fourth year thereafter for a term of four (4) years?"),
 (93, QN, "City of Rocky River", "ROCKY RIVER", "Rocky River", CA + ": Article IV, Section 2 (B) (removal of the Director of Law)", "Shall Article IV, Section 2 (B) of the Charter of the City of Rocky River be amended to provide that Council may, by a two-thirds (2/3) vote of the members of Council after public hearing, expel or remove the Director of Law from office for gross misconduct, malfeasance, nonfeasance, misfeasance in or disqualification for office; for violation of their oath of office; for conviction while in office of a crime involving moral turpitude; or for mental or physical disability rendering it impossible for them to perform the duties of the Director of Law?"),
 (94, QN, "City of Rocky River", "ROCKY RIVER", "Rocky River", CA + ": Article VIII, Section 2 (recall elections)", "Shall Article VIII, Section 2 of the Charter of the City of Rocky River be amended to provide that within twenty (20) days of the filing of a recall petition, the Clerk, in consultation with the Board of Elections, shall determine whether or not it meets the requirements to hold a recall election; and to expand the timeframe for holding a recall election from between thirty (30) and forty-five (45) days, to not less than sixty (60) and no more than seventy-five (75) days after the delivery of notice to the elected officer of a sufficient petition calling for the officer to resign?"),
 (95, QN, "City of Rocky River", "ROCKY RIVER", "Rocky River", CA + ": Article IX (non-partisan municipal elections)", "Shall Article IX of the Charter of the City of Rocky River be amended by amending Sections 1, 2, and 3, and eliminating sections 4 and 5, to provide that beginning in 2027, all municipal elections shall be non-partisan elections; that the names of two (2) persons receiving the highest number of votes in the primary election held in September for each office shall be nominated to be candidates for the offices of mayor, law director and ward councilman at the next succeeding regular municipal elections; for candidates for the offices of at-large councilmen, the names of five (5) persons receiving the highest number of votes shall be nominated at the next succeeding regular municipal elections; and to provide that a petition shall require signatures of registered electors of not less than fifty (50) for ward councilman, and one hundred fifty (150) for councilman-at-large, mayor, and law director?"),
 (96, QN, "City of Seven Hills", "SEVEN HILLS", "Seven Hills", CA + ": Article V, Section 8 (d) (zoning variances)", "Shall Article V, Section 8 (d) of the Charter of the City of Seven Hills be amended to provide that the determination of the Zoning Board of Appeals on any variance request shall be deemed final and shall not require further approval by any other municipal body, and subject only to judicial appeal as permitted under State Law (Ohio Revised Code Section 713.11)?"),
 (97, LQ, "City of Shaker Heights", "SHAKER HEIGHTS", "Shaker Heights precinct 00-H", "Local liquor option: Shaker Smoke & Beverage (Sunday)", "Shall the sale of wine and mixed beverages be permitted for sale on Sunday by Shivay 22, L.L.C., dba Shaker Smoke & Beverage an applicant for a D-6 liquor permit who is engaged in the business of operating a carryout/grocery store at 3753 Lee Road, Shaker Heights, OH 44128 in this precinct?"),
 (98, QN, "City of Solon", "SOLON", "Solon", CA + ": Article VI, Section 10.A (Master Plan review)", "Shall Article VI, Section 10.A of the Charter of the City of Solon be amended to provide that on or before January of 2029 the Director of Planning and Community Development with the assistance of the Master Plan Citizen’s Committee, shall commence a comprehensive review of the City of Solon Master Plan; and to add subsection (d) to provide the Planning Department and Economic Development Department shall jointly provide biannual reports to City leadership and relevant stakeholders detailing a summary of key accomplishments, including notable project completions and measurable wins, clear identification of risks, constraints or challenges, an outlook of anticipated projects, opportunities and priorities, as well as a detailed summary of required resources necessary to successfully execute identified initiatives?"),
 (99, QN, "City of Solon", "SOLON", "Solon", CA + ": Article XIV, Sections 1 and 2 (ward votes on zoning)", "Shall Article XIV, Sections 1 and 2 of the Charter of the City of Solon be amended to repeal the requirement that any zoning district change or zoning use change be approved by a majority of the electors in each ward in which a change in zoning classification, zoning district, or zoning use change of any property is located?"),
 (100, QN, "City of Solon", "SOLON", "Solon", CA + ": Article XIV, new Section 5 (Industrial Core Area)", "Shall Article XIV of the Charter of the City of Solon be amended to add Section 5 to provide that Council shall adopt a procedure and process for the Zoning and Development of the Industrial Core Area as identified and described within the City of Solon Master Plan, which shall not employ the procedure and process contained in Sections 1 and 2 in Article XIV, which requires that any ordinance effecting a change in the zoning classification, zoning map change, or zoning use shall be approved by a majority of electors voting thereon?"),
 (101, LQ, "City of South Euclid", "SOUTH EUCLID", "South Euclid precinct 01-D", "Local liquor option: Green Luxury Loft", "Shall the sale of spirituous liquor be permitted by VMPR, L.L.C. (dba Green Luxury Loft), an applicant for D3 and D5 liquor permits who is engaged in the business of operating a wedding/event venue at 800 South Green Road, South Euclid, OH 44121 in this precinct?"),
 (102, LQ, "City of South Euclid", "SOUTH EUCLID", "South Euclid precinct 01-D", "Local liquor option: Green Luxury Loft (Sunday)", "Shall the sale of wine and mixed beverages and spirituous liquor be permitted for sale on Sunday by VMPR, L.L.C. (dba Green Luxury Loft) an applicant for a D-6 liquor permit who is engaged in the business of operating a wedding/event venue at 800 South Green Road, South Euclid, OH 44121 in this precinct?"),
 (104, LQ, "City of University Heights", "UNIVERSITY HEIGHTS", "University Heights precinct 00-E", "Local liquor option: Trader Joe’s #599 (Sunday)", "Shall the sale of wine and mixed beverages be permitted for sale on Sunday by Trader Joe’s East Inc. dba Trader Joe’s #599 an applicant for a D-6 liquor permit who is engaged in the business of operating a family oriented, full-service grocery store at 2643 Warrensville Center Road, University Heights, OH 44118 in this precinct?"),
 (106, QN, "City of Westlake", "WESTLAKE", "Westlake", "Proposed zoning amendment: Center Ridge Road", "Shall the Zoning Map of the City of Westlake be amended by changing the zoning of certain land located at 27398, 27408, 27438, and 27450 Center Ridge Road, being all of PP#’s 212-30-008, 212-30-009, 212-30-010 and 212-30-011, from Office Building, R-1F-80 and R-MF-24 Districts to R-MF-24 District?"),
 (107, QN, "City of Mayfield Heights", "MAYFIELD HEIGHTS", "Mayfield Heights", "Proposed zoning amendment (by petition): Parkland Boulevard", "Shall the Zoning Map of the City of Mayfield Heights be amended to change the zoning classification of certain property located on Parkland Boulevard, assigned PP# 863-20-003, from U-2A(1): Planned Unit Development Districts, Minimum Three Acres, to U-7: Headquarters or Executive Offices Park Districts?"),
]
